// Collect learned kanji, pick today's grammar point from the Grammar Bank, and pick a topic
const cfg = $('Set Configuration Values').first().json;
const level = String(cfg.jlpt_level || 'N3').trim().toUpperCase();

// Sheet headers are trimmed and lowercased, so a header like "Nuance " still works
const normKeys = o => Object.fromEntries(Object.entries(o || {}).map(([k, v]) => [String(k).trim().toLowerCase(), v]));

// 1. Learned kanji
const learned = $('Read Learned Kanji from Sheets').all()
  .map(i => normKeys(i.json))
  .filter(r => String(r.learned).trim().toUpperCase() === 'TRUE')
  .map(r => String(r.kanji ?? '').trim())
  .filter(Boolean);
if (learned.length === 0) {
  throw new Error('No learned kanji found. Add kanji to the "Kanji" tab and set "learned" to TRUE.');
}

// 2. Grammar already taught ("～ように" and "ように" count as the same pattern)
const norm = s => String(s ?? '').replace(/[～〜~\s]/g, '');
const usedPatterns = $('Read Used Grammar from Sheets').all()
  .map(i => String(normKeys(i.json).grammar_pattern ?? '').trim())
  .filter(Boolean);
const used = new Set(usedPatterns.map(norm));

// 3. Next unused grammar point from the Grammar Bank (rows for this level, in sheet order)
const bank = $('Read Grammar Bank from Sheets').all()
  .map(i => normKeys(i.json))
  .filter(r => r && r.pattern && (!r.level || String(r.level).trim().toUpperCase() === level));
const remaining = bank.filter(r => !used.has(norm(r.pattern)));
const next = remaining[0];

let grammar_point = null;
let grammar_instruction;
if (next) {
  grammar_point = {
    pattern: String(next.pattern),
    reading: String(next.reading ?? ''),
    meaning: String(next.meaning ?? ''),
    formation: String(next.formation ?? ''),
    nuance: String(next.nuance ?? ''),
    compare_with: String(next.compare_with ?? ''),
    difference: String(next.difference ?? '')
  };
  grammar_instruction = [
    "TODAY'S GRAMMAR POINT (verified facts: copy them into the grammar fields unchanged and write the examples yourself)",
    'Pattern: ' + grammar_point.pattern + ' (' + grammar_point.reading + ')',
    'Meaning: ' + grammar_point.meaning,
    'Formation: ' + grammar_point.formation,
    'Nuance: ' + grammar_point.nuance,
    'Do not confuse with: ' + grammar_point.compare_with + ' (' + grammar_point.difference + ')'
  ].join('\n');
} else {
  grammar_instruction = 'Choose ONE common JLPT ' + level + ' grammar pattern that is NOT in this list of patterns already taught: '
    + (usedPatterns.slice(-200).join('、') || 'none yet')
    + '. Make sure the formation, nuance and comparison you write are accurate.';
}

// 4. Topic of the day (rotates through the list in Config)
const defaultTopics = [
  'daily routine', 'shopping', 'travel in Japan', 'work and office life',
  'weather and seasons', 'food and cooking', 'friends and hobbies', 'health',
  'studying a language', 'public transport', 'festivals and events',
  'moving to a new apartment', 'a weekend trip', 'a problem at work'
];
const configTopics = String(cfg.topics ?? '').split(',').map(t => t.trim()).filter(Boolean);
const topics = configTopics.length ? configTopics : defaultTopics;
const now = new Date();
const dayOfYear = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);

return [{
  json: {
    jlpt_level: level,
    kanji_list: [...new Set(learned.join(''))].join(''),
    kanji_count: learned.length,
    grammar_point,
    grammar_instruction,
    grammar_bank_remaining: Math.max(0, remaining.length - (next ? 1 : 0)),
    passage_length: String(cfg.passage_length || '150-250'),
    topic: topics[dayOfYear % topics.length]
  }
}];

