// Find kanji outside the learned list in every Japanese field, with short snippets showing where they appear
function checkKanji(lesson, kanjiList) {
  const allowed = new Set([...kanjiList, '々']);
  const texts = [
    lesson.passage?.title_jp,
    lesson.passage?.jp,
    ...(lesson.grammar?.examples || []).map(e => e.jp),
    ...(lesson.questions || []).flatMap(q => [q.q_jp, q.answer])
  ].filter(Boolean).map(String);

  const found = texts.join('').match(/\p{Script=Han}/gu) || [];
  const outside_kanji = [...new Set(found.filter(k => !allowed.has(k)))];

  const outside_words = [];
  for (const t of texts) {
    for (const m of t.matchAll(/\p{Script=Han}+/gu)) {
      if ([...m[0]].some(k => !allowed.has(k))) {
        const start = Math.max(0, m.index - 3);
        outside_words.push(t.slice(start, m.index + m[0].length + 3));
      }
    }
  }
  return { outside_kanji, outside_words: [...new Set(outside_words)] };
}

// Line up a Japanese sentence with its kana version and return [kanji word, reading] pairs
function alignSentence(j, k) {
  const parts = j.match(/[\p{Script=Han}々]+|[^\p{Script=Han}々]+/gu) || [];
  const isKanji = p => /[\p{Script=Han}々]/u.test(p);
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  let m;
  try {
    m = k.match(new RegExp('^' + parts.map(p => isKanji(p) ? '(.+?)' : esc(p)).join('') + '$', 'u'));
  } catch (e) {
    return null;
  }
  if (!m) return null;
  return parts.filter(isKanji).map((run, i) => [run, m[i + 1]]);
}

// Align sentence by sentence, so one furigana mistake only affects its own sentence
// Katakana and hiragana count as the same when lining up furigana (バス = ばす)
const toHiragana = s => s.replace(/[\u30A1-\u30F6]/g, c => String.fromCharCode(c.charCodeAt(0) - 0x60));
const splitSentences = s => toHiragana(String(s ?? '').replace(/\s+/g, '')).split(/(?<=[。！？!?])/).filter(Boolean);
function alignText(jp, kana) {
  const js = splitSentences(jp);
  const ks = splitSentences(kana);
  if (!js.length) return { pairs: [], failed: [] };
  const hasKanji = s => /[\p{Script=Han}々]/u.test(s);
  if (js.length !== ks.length) {
    const whole = ks.length && !hasKanji(ks.join('')) ? alignSentence(js.join(''), ks.join('')) : null;
    return whole ? { pairs: whole, failed: [] } : { pairs: [], failed: js.map((_, i) => i + 1) };
  }
  const pairs = [];
  const failed = [];
  js.forEach((s, i) => {
    const r = hasKanji(ks[i]) ? null : alignSentence(s, ks[i]);
    if (r) pairs.push(...r);
    else failed.push(i + 1);
  });
  return { pairs, failed };
}

// Rewrite words that contain unlearned kanji in hiragana, using readings from the kana fields
function autoHiragana(jp, kana, allowed, dict) {
  if (!jp) return jp;
  for (const [run, reading] of alignText(jp, kana).pairs) {
    if (!dict[run]) dict[run] = reading;
  }
  return String(jp).replace(/[\p{Script=Han}々]+/gu, run =>
    [...run].some(c => !allowed.has(c)) && dict[run] ? dict[run] : run);
}

const answerJapanese = a => String(a ?? '').match(/^([\s\S]*?)(\s*[（(][\s\S]*)?$/)[1];
const answerEnglish = a => String(a ?? '').match(/^([\s\S]*?)(\s*[（(][\s\S]*)?$/)[2] || '';

function fixUnlearnedKanji(lesson, kanjiList) {
  const allowed = new Set([...kanjiList, '々']);
  const dict = {}; // readings found so far, reused for fields whose kana could not be aligned
  const fixed = JSON.parse(JSON.stringify(lesson));
  const p = fixed.passage || {};
  p.jp = autoHiragana(p.jp, p.kana, allowed, dict);
  for (const ex of fixed.grammar?.examples || []) ex.jp = autoHiragana(ex.jp, ex.kana, allowed, dict);
  p.title_jp = autoHiragana(p.title_jp, p.title_kana, allowed, dict);
  for (const q of fixed.questions || []) {
    q.q_jp = autoHiragana(q.q_jp, q.q_kana, allowed, dict);
    q.answer = autoHiragana(answerJapanese(q.answer), q.answer_kana, allowed, dict) + answerEnglish(q.answer);
  }
  return fixed;
}

// List every furigana line that does not match its Japanese text (or contains kanji)
function checkFurigana(lesson) {
  const issues = [];
  const check = (label, jp, kana) => {
    if (!jp) return;
    const { failed } = alignText(jp, kana);
    const count = splitSentences(jp).length;
    if (failed.length) issues.push(count > 1 ? label + ' (sentence ' + failed.join(', ') + ')' : label);
  };
  check('title', lesson.passage?.title_jp, lesson.passage?.title_kana);
  check('passage', lesson.passage?.jp, lesson.passage?.kana);
  (lesson.grammar?.examples || []).forEach((ex, i) => check('example ' + (i + 1), ex.jp, ex.kana));
  (lesson.questions || []).forEach((q, i) => {
    check('question ' + (i + 1), q.q_jp, q.q_kana);
    check('answer ' + (i + 1), answerJapanese(q.answer), q.answer_kana);
  });
  return issues;
}

// ---- Main ----
const ctx = $('Prepare Lesson Context').first().json;
const draft = $('Validate Lesson Draft').first().json;

// Use the proofread lesson, or the draft if proofreading failed
const out = $input.first().json.output;
const proofread = Boolean(out?.grammar && out?.passage && Array.isArray(out?.questions));
let lesson = proofread
  ? { grammar: out.grammar, passage: out.passage, questions: out.questions }
  : { grammar: draft.grammar, passage: draft.passage, questions: draft.questions };

// Grammar facts from the Grammar Bank always win over the AI's version
const gp = ctx.grammar_point;
if (gp) {
  lesson.grammar = {
    ...lesson.grammar,
    pattern: gp.pattern,
    pattern_reading: gp.reading,
    meaning_en: gp.meaning,
    formation: gp.formation,
    nuance: gp.nuance,
    compare: { pattern: gp.compare_with, difference: gp.difference }
  };
}

// Rewrite words with unlearned kanji in hiragana, then report anything left over
lesson = fixUnlearnedKanji(lesson, ctx.kanji_list);

return [{ json: {
  ...lesson,
  ...checkKanji(lesson, ctx.kanji_list),
  furigana_issues: checkFurigana(lesson),
  proofread,
  grammar_from_bank: Boolean(gp),
  jlpt_level: ctx.jlpt_level,
  topic: ctx.topic
} }];

// Build a Microsoft Teams Adaptive Card with tap-to-reveal sections
const L = $input.first().json;
const g = L.grammar;
const p = L.passage;
const qs = L.questions || [];
const examples = g.examples || [];
const today = $now.toFormat('yyyy-MM-dd'); // uses the workflow timezone

const text = (t, opts = {}) => ({ type: 'TextBlock', text: String(t ?? ''), wrap: true, ...opts });
const hidden = (id, items) => ({ type: 'Container', id, isVisible: false, style: 'emphasis', items });
const toggle = (title, id) => ({ type: 'Action.ToggleVisibility', title, targetElements: [id] });
const actions = (...acts) => ({ type: 'ActionSet', actions: acts });

const body = [];

// Header
body.push(text('JLPT ' + L.jlpt_level + ' Daily Lesson', { size: 'Large', weight: 'Bolder' }));
body.push(text(today + ' · Topic: ' + L.topic, { isSubtle: true, spacing: 'None' }));

// Grammar section
body.push(text('🧩 Grammar: ' + g.pattern, { size: 'Medium', weight: 'Bolder', separator: true, spacing: 'Large' }));
body.push(text(g.pattern_reading + '  —  ' + g.meaning_en, { spacing: 'Small' }));
body.push({
  type: 'FactSet',
  facts: [
    { title: 'Formation', value: String(g.formation ?? '') },
    { title: 'Nuance', value: String(g.nuance ?? '') },
    { title: 'Don\'t confuse with', value: (g.compare?.pattern ?? '') + ' — ' + (g.compare?.difference ?? '') }
  ]
});
body.push(text('Examples', { weight: 'Bolder' }));
examples.forEach((ex, i) => body.push(text((i + 1) + '. ' + ex.jp, { spacing: 'Small' })));
body.push(actions(toggle('Show readings & English', 'gram_ex')));
body.push(hidden('gram_ex', examples.flatMap((ex, i) => [
  text((i + 1) + '. ' + ex.kana, { weight: 'Bolder', spacing: i === 0 ? 'None' : 'Medium' }),
  text(ex.romaji, { isSubtle: true, spacing: 'None' }),
  text(ex.en, { spacing: 'None' })
])));

// Reading passage section
body.push(text('📖 Reading: ' + p.title_jp, { size: 'Medium', weight: 'Bolder', separator: true, spacing: 'Large' }));
body.push(text(p.jp, { size: 'Medium' }));
if (L.furigana_issues?.length) {
  body.push(text('Note: the furigana may not match the Japanese in: ' + L.furigana_issues.join(', '), { color: 'Warning', size: 'Small' }));
}
if (L.proofread === false) {
  body.push(text('Note: proofreading failed today, so this is the unchecked draft.', { color: 'Warning', size: 'Small' }));
}
if (L.outside_kanji?.length) {
  body.push(text('Note: this lesson still uses kanji not on your list: ' + L.outside_kanji.join(' '), { color: 'Attention', size: 'Small' }));
}
body.push(actions(
  toggle('Furigana', 'p_kana'),
  toggle('Romaji', 'p_romaji'),
  toggle('English', 'p_en'),
  toggle('Vocabulary', 'p_vocab')
));
body.push(hidden('p_kana', [text(p.kana)]));
body.push(hidden('p_romaji', [text(p.romaji)]));
body.push(hidden('p_en', [text(p.en)]));
body.push(hidden('p_vocab', (p.new_words || []).map(w =>
  text(w.word + ' (' + w.reading + ') — ' + w.meaning, { spacing: 'Small' })
)));

// Comprehension questions
body.push(text('❓ Questions', { size: 'Medium', weight: 'Bolder', separator: true, spacing: 'Large' }));
qs.forEach((q, i) => body.push(text((i + 1) + '. ' + q.q_jp, { spacing: 'Small' })));
body.push(actions(toggle('Furigana', 'q_kana'), toggle('Show answers', 'answers')));
body.push(hidden('q_kana', qs.map((q, i) => text((i + 1) + '. ' + (q.q_kana || q.q_jp), { spacing: 'Small' }))));
body.push(hidden('answers', qs.flatMap((q, i) => [
  text((i + 1) + '. ' + q.q_en, { isSubtle: true, spacing: i === 0 ? 'None' : 'Medium' }),
  text('→ ' + q.answer, { spacing: 'None' }),
  ...(q.answer_kana ? [text(q.answer_kana, { isSubtle: true, spacing: 'None' })] : [])
])));

const payload = {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    contentUrl: null,
    content: {
      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
      type: 'AdaptiveCard',
      version: '1.4',
      msteams: { width: 'Full' },
      body
    }
  }]
};

return [{ json: { payload, log_pattern: g.pattern, log_meaning: g.meaning_en } }];
